def _card(data, cid):
    return next(d for d in data['deals'] if d['id'] == cid)


def _oneoff_apply(data, strict=True):
    import fact_edit_guard
    n = 0
    # --- berizaryad: продавец
    c = _card(data, 'berizaryad')
    if c.get('seller') != BZ_SELLER_NEW:
        assert c.get('seller') == BZ_SELLER_OLD and not c.get('seller_id'), (c.get('seller'), c.get('seller_id'))
        c['seller'] = BZ_SELLER_NEW
        fact_edit_guard.log(c, 'seller', BZ_SELLER_NEW, BZ_Q, KOMM_DEALS, ONEOFF_BY, ONEOFF_DAY)
        c.setdefault('party_evidence', {})['seller'] = [{'value': BZ_SELLER_NEW, 'field': 'seller',
                                                         'method': 'source_text', 'url': KOMM_DEALS}]
        c.setdefault('accepted_notes', {}).setdefault('no_profile', {})['seller'] = BZ_NOTE
        n += 1
    # --- gfc3c7ec8: профиль Hygienic — отрасль и описание
    p = data['companies'][HYG_PROFILE]
    if p.get('ind') != HYG_IND_NEW or p.get('desc') != HYG_DESC_NEW:
        assert p.get('ind') in (HYG_IND_OLD, HYG_IND_NEW) and p.get('desc') in (HYG_DESC_OLD, HYG_DESC_NEW), \
            (p.get('ind'), p.get('desc'))
        p['ind'], p['desc'] = HYG_IND_NEW, HYG_DESC_NEW
        n += 1
    # --- заметки этапов
    for cid, k, old_note, new_note in EVENT_NOTES:
        e = _card(data, cid)['events'][k]
        if e.get('note') != new_note:
            assert e.get('note') == old_note, (cid, k, e.get('note'))
            e['note'] = new_note
            n += 1
    # --- заметки о поиске сторон и о реестре (находки seller_search / buyer_search / registry_owners_unchecked)
    for cid, path, text in (('g91ec3558', ('no_profile', 'seller'), AZB_SELLER_NOTE),
                            ('g91ec3558', ('checked', 'registry_owners'), AZB_CHECKED),
                            ('gaa7602e7', ('no_profile', 'buyer'), DH_BUYER_NOTE),
                            ('g889e051d', ('checked', 'registry_owners'), VOS_CHECKED),
                            ('baltika', ('checked', 'registry_owners'), BALT_CHECKED)):
        c = _card(data, cid)
        notes = c.setdefault('accepted_notes', {}).setdefault(path[0], {})
        if notes.get(path[1]) != text:
            notes[path[1]] = text
            n += 1
    return n


def _oneoff_main(write):
    import json
    import os
    import sys
    root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
    sys.path.insert(0, os.path.join(root, 'pipeline'))
    import fact_edit_guard
    import mass_edit_guard
    path = os.path.join(root, 'static', 'data', 'deals_promoted.json')
    raw = open(path, encoding='utf-8').read()
    old, data = json.loads(raw), json.loads(raw)
    n = _oneoff_apply(data, strict=write)
    if not n:
        print('Уже применено.')
        return 0
    mass_edit_guard.check(old, data, os.environ.get('MASS_OK'))
    bad = fact_edit_guard.unbacked(old, data)
    assert not bad, bad
    if not write:
        print('Сухой прогон: %d правок. Запись — с ключом --write.' % n)
        return 0
    fresh_raw = open(path, encoding='utf-8').read()
    fresh = json.loads(fresh_raw)
    _oneoff_apply(fresh)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(json.dumps(fresh, ensure_ascii=False, indent=1) + ('\n' if fresh_raw.endswith('\n') else ''))
    print('ЗАПИСАНО: %d правок.' % n)
    return 0


if __name__ == '__main__':
    import sys
    sys.exit(_oneoff_main('--write' in sys.argv[1:]))
